        n = len(formula[0])
        matrix = [[0] * (n + 1) for _ in range(n)]
        for clause in formula:
            for i, literal in enumerate(clause):
                if literal.startswith("~"):
                    j = int(literal[1:]) - 1
                    matrix[i][j] = -1
                else:
                    j = int(literal) - 1
                    matrix[i][j] = 1
        matrix.append([0] * n + [1])
        for i in range(n):
