    clauses = []
    for _ in range(n):
        clause = random.sample(literals, 2)
        clause.append(random.choice(['', '¬']))
        clauses.append(clause)
    return clauses

def aic(formula):
    literals = set()
    for clause in formula:
        for literal in clause:
            if literal.startswith('¬'):
                literal = literal[1:]
            literals.add(literal)

    literal_to_index = {literal: i for i, literal in enumerate(literals)}
    matrix = [[0] * len(literals) for _ in range(len(literals))]

    for clause in formula:
        if clause[-1]:
            continue
        literal1 = clause[0]
        literal2 = clause[1]
        index1 = literal_to_index[literal1]
        index2 = literal_to_index[literal2]

        matrix[index1][index2] += 1
        matrix[index2][index1] += 1

    rank = gaussian_elimination(matrix)
    return len(literals) - rank

def gaussian_elimination(matrix):
    n = len(matrix)
    for i in range(n):
        if matrix[i][i] == 0:
            for j in range(i+1, n):
                if matrix[j][i] != 0:
                    matrix[i], matrix[j] = matrix[j], matrix[i]
                    break
            else:
                continue

        pivot = Fraction(matrix[i][i])
        for j in range(n):
            matrix[i][j] /= pivot

        for j in range(n):
            if i == j:
                continue
            factor = Fraction(matrix[j][i])
            for k in range(n):
                matrix[j][k] -= factor * matrix[i][k]

    rank = 0
    for row in matrix:
        if any(row):
            rank += 1

    return rank

def run_trial(seed: int) -> dict:
